import { mountIceberg, parseItems, type IcebergItem } from "../src/index.js";
import "../styles.css";

const host = document.querySelector<HTMLElement>("#iceberg");
if (!host) throw new Error("Iceberg host is missing.");

const [itemsSource, contributors] = await Promise.all([
  fetch("items.toml", { cache: "no-store" }).then(response => response.text()),
  // Generated by scripts/fetch-contributors.ts; optional.
  fetch("contributors.json", { cache: "no-store" })
    .then(response => (response.ok ? response.json() : {}))
    .catch(() => ({})) as Promise<Record<string, Partial<IcebergItem>>>,
]);
const items = parseItems(itemsSource).map(item => ({ ...item, ...contributors[item.slug] }));

mountIceberg(host, {
  items,
  cardWidth: 460,
  viewSelector: true,
  aboveWaterLabelStretch: 1,
  aboveWaterRing: true,
  aboveWaterSpread: 2.2,
  assets: {
    model: "assets/models/iceberg-web.glb",
    environment: "assets/environment/ocean-panorama.hdr",
    sky: "assets/environment/polar-cirrus.webp",
    relief: "assets/textures/glacial-relief.webp",
  },
});
